const KEY='matrice_ptf_senegal_v2';
const rubriques=['RAC','RNV','PADO / STRATÉGIE DE SORTIE PMA','ODD','PLAN D’ACTION DE DAR EL SALAM','INCLUSION ET GROUPES VULNÉRABLES ?','PLATEFORME INFORMATISÉE','ÉTUDES','SUIVI INFRA ANNUEL','GUIDE HARMONISÉ'];
const fields={multi:['partenaire','sigle','categorie','operateur','secteur','observation'],bi:['partenaire','sigle','categorie','operateur','secteur','observation'],hors:['numero','etablissement','sigle','nature','pays','instrument','observation']};
let data=JSON.parse(localStorage.getItem(KEY)||'null')||{partners:[],multi:[],bi:[],hors:[],activites:[],partenairesFiches:[],indicateurs:{},settings:{}};
data.partners=(data.partners||[]).map(p=>({...p,type:p.type||'Public'}));
data.multi=data.multi||[];data.bi=data.bi||[];data.hors=data.hors||[];data.activites=data.activites||[];data.partenairesFiches=data.partenairesFiches||[];data.indicateurs=data.indicateurs||{};
const FIXED_PLATFORM_NAME='MATRICE PARTENAIRE ET PTF SÉNÉGAL'; const FIXED_SUBTITLE='Gestion • Suivi • Analyse • Données'; const FIXED_FOOTER='SDF Technologie — Solution Digital du Futur @2026';
const defaultSettings={platformName:FIXED_PLATFORM_NAME,subtitle:FIXED_SUBTITLE,footer:FIXED_FOOTER,prenom:'',nom:'',ministere:'',service:'',poste:'',phone:'',email:'',username:'admin',rubriques:[...rubriques],partnerCategories:['Institutionnelle','Multilatéral','Bilatéral','Secteur privé','ONG','Société civile','Elus locaux','Autres'],contributionTypes:[],alertStatuses:['Aucune alerte','À surveiller','Alerte'],partnerContributionTypes:['Financier','Technique','Plaidoyer'],partnerDeliverableTypes:['Rapport','Étude','Formation','Autre'],partnerLitigationResolutions:['Aucun litige','Accord amiable','Médiation','Arbitrage','Autre'],activityAxes:[]};
data.settings={...defaultSettings,...(data.settings||{})};delete data.settings.password;delete data.settings.currentPassword;delete data.settings.newPassword;
['rubriques','partnerCategories','contributionTypes','alertStatuses','partnerContributionTypes','partnerDeliverableTypes','partnerLitigationResolutions','activityAxes'].forEach(k=>{if(!Array.isArray(data.settings[k]))data.settings[k]=defaultSettings[k].slice();data.settings[k]=[...new Set(data.settings[k].map(v=>String(v).trim()).filter(Boolean))]});
data.settings.rubriques=[...new Set(data.settings.rubriques.map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerCategories=[...new Set(data.settings.partnerCategories.map(v=>String(v).trim()).filter(Boolean))];data.settings.contributionTypes=[...new Set(data.settings.contributionTypes.map(v=>String(v).trim()).filter(Boolean))];data.settings.alertStatuses=[...new Set(data.settings.alertStatuses.map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerContributionTypes=[...new Set(data.settings.partnerContributionTypes.map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerDeliverableTypes=[...new Set(data.settings.partnerDeliverableTypes.map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerLitigationResolutions=[...new Set(data.settings.partnerLitigationResolutions.map(v=>String(v).trim()).filter(Boolean))];data.settings.activityAxes=[...new Set((data.settings.activityAxes||[]).map(v=>String(v).trim()).filter(Boolean))];data.activites=(data.activites||[]).map(x=>{const axes=normalizeMultiValue(x.axes||x.axe);const partenaires=normalizeMultiValue(x.partenaires||x.partenaire);return {...x,axes,partenaires,axe:axes.join(' | '),partenaire:partenaires.join(' | ')}});rubriques.splice(0,rubriques.length,...data.settings.rubriques);data.partners.forEach(p=>{p.values=p.values||{};rubriques.forEach(r=>{p.values[r]=p.values[r]||{interet:'',influence:'',contribution:''}})});data.partenairesFiches=(data.partenairesFiches||[]).map(x=>({...x,zone:x.zone||'',siteWeb:x.siteWeb||'',typeContribution:x.typeContribution||'',typeLivrable:x.typeLivrable||x.livrables||'',resolutionLitiges:x.resolutionLitiges||x.litiges||''}));

let edit={multi:null,bi:null,hors:null,activites:null,partenairesFiches:null};
let partenaireFicheEdit=null; let charts={};

let apiAuthenticated = false;
let cloudSyncTimer = null;
let cloudSyncRunning = false;
let lastCloudSyncData = '';

function setCloudStatus(message, state='neutral') {
 document.querySelectorAll('#cloudSyncStatus').forEach(el=>{el.textContent=message;el.style.color=state==='ok'?'#15803d':state==='error'?'#b42318':'#64748b';});
}
async function apiRequest(path, options={}) {
 const response=await fetch(path,{credentials:'same-origin',headers:{'Content-Type':'application/json',...(options.headers||{})},...options});
 let payload={}; try{payload=await response.json();}catch(_){payload={};}
 if(!response.ok){const err=new Error(payload.error||`Erreur API (${response.status})`);err.status=response.status;throw err;}
 return payload;
}
function hasLocalData(){return Boolean((data.partners||[]).length||(data.activites||[]).length||(data.partenairesFiches||[]).length||Object.keys(data.indicateurs||{}).length);}
function applyRemoteState(remote){
 if(!remote||typeof remote!=='object')return;
 data={...data,...remote};
 data.partners=Array.isArray(data.partners)?data.partners:[];
 data.activites=Array.isArray(data.activites)?data.activites:[];
 data.partenairesFiches=Array.isArray(data.partenairesFiches)?data.partenairesFiches:[];
 data.indicateurs=data.indicateurs&&typeof data.indicateurs==='object'?data.indicateurs:{};
 data.settings={...defaultSettings,...(data.settings||{})};
 ['rubriques','partnerCategories','contributionTypes','alertStatuses','partnerContributionTypes','partnerDeliverableTypes','partnerLitigationResolutions','activityAxes'].forEach(k=>{if(!Array.isArray(data.settings[k]))data.settings[k]=defaultSettings[k].slice();data.settings[k]=[...new Set(data.settings[k].map(v=>String(v).trim()).filter(Boolean))];});
 delete data.settings.password; delete data.settings.currentPassword; delete data.settings.newPassword;
 rubriques.splice(0,rubriques.length,...data.settings.rubriques);
 data.partners=data.partners.map(p=>({...p,type:p.type||'Public',values:p.values||{}}));
 data.partners.forEach(p=>rubriques.forEach(r=>{p.values[r]=p.values[r]||{interet:'',influence:'',contribution:''};}));
 data.activites=data.activites.map(x=>{const axes=normalizeMultiValue(x.axes||x.axe);const partenaires=normalizeMultiValue(x.partenaires||x.partenaire);return {...x,axes,partenaires,axe:axes.join(' | '),partenaire:partenaires.join(' | ')};});
 data.partenairesFiches=data.partenairesFiches.map(x=>({...x,zone:x.zone||'',siteWeb:x.siteWeb||'',typeContribution:x.typeContribution||'',typeLivrable:x.typeLivrable||x.livrables||'',resolutionLitiges:x.resolutionLitiges||x.litiges||''}));
 localStorage.setItem(KEY,JSON.stringify(data));
 applyPlatformSettings(); rebuildNavigation(); renderPartners(); renderMatrix(); renderActivites(); renderPartenairesFiches(); syncConfigLists(); renderIndicateurs(); updateStats();
}
async function syncStateToCloud(){
 if(!apiAuthenticated||cloudSyncRunning)return;
 cloudSyncRunning=true;const snapshot=JSON.stringify(data);
 try{await apiRequest('/api/state',{method:'PUT',body:snapshot});lastCloudSyncData=snapshot;setCloudStatus('Synchronisé avec Cloudflare','ok');}
 catch(error){setCloudStatus(error.status===401?'Session expirée':'Synchronisation impossible', 'error');if(error.status===401){apiAuthenticated=false;showAuthScreen('Votre session a expiré. Reconnectez-vous.');}}
 finally{cloudSyncRunning=false;}
}
function scheduleCloudSync(){if(!apiAuthenticated)return;setCloudStatus('Enregistrement…');clearTimeout(cloudSyncTimer);cloudSyncTimer=setTimeout(()=>{void syncStateToCloud();},650);}
async function loadStateFromCloud(){
 const result=await apiRequest('/api/state');
 if(result.state){applyRemoteState(result.state);lastCloudSyncData=JSON.stringify(data);}
 else if(hasLocalData()){await apiRequest('/api/state',{method:'PUT',body:JSON.stringify(data)});lastCloudSyncData=JSON.stringify(data);}
 setCloudStatus('Connecté à Cloudflare D1','ok');
}
function showAuthScreen(message=''){
 const auth=document.getElementById('authScreen'),app=document.getElementById('appRoot');
 if(auth){auth.hidden=false;const err=document.getElementById('loginError');if(err){err.textContent=message;err.style.display=message?'block':'none';}const login=document.getElementById('loginForm'),force=document.getElementById('forcePasswordForm');if(login)login.hidden=false;if(force)force.hidden=true;const forceErr=document.getElementById('forcePasswordError');if(forceErr){forceErr.textContent='';forceErr.style.display='none';}}
 if(app)app.hidden=true;
}
function showForcedPasswordScreen(){
 const auth=document.getElementById('authScreen'),app=document.getElementById('appRoot');if(auth)auth.hidden=false;if(app)app.hidden=true;
 const login=document.getElementById('loginForm'),force=document.getElementById('forcePasswordForm');if(login)login.hidden=true;if(force)force.hidden=false;
 const error=document.getElementById('forcePasswordError');if(error){error.textContent='';error.style.display='none';}
}
function showApplication(){const auth=document.getElementById('authScreen'),app=document.getElementById('appRoot');if(auth)auth.hidden=true;if(app)app.hidden=false;document.querySelectorAll('.logout-btn').forEach(button=>button.hidden=!apiAuthenticated);}
async function bootstrapCloudAccount(){
 try{
  const response=await fetch('/api/auth/me',{credentials:'same-origin',headers:{Accept:'application/json'}});
  if(response.status===404){showApplication();setCloudStatus('Mode local — API non configurée');return;}
  if(response.status===401){showAuthScreen();return;}
  if(!response.ok){showAuthScreen('Le service sécurisé est temporairement indisponible. Réessayez.');return;}
  const session=await response.json();apiAuthenticated=true;
  if(session.user?.mustChangePassword){showForcedPasswordScreen();return;}
  await loadStateFromCloud();
  if(session.user?.profile){Object.assign(data.settings,{prenom:session.user.profile.firstName||'',nom:session.user.profile.lastName||'',ministere:session.user.profile.ministry||'',service:session.user.profile.department||'',poste:session.user.profile.position||'',phone:session.user.profile.phone||'',email:session.user.profile.email||'',username:session.user.username||'admin'});localStorage.setItem(KEY,JSON.stringify(data));applyPlatformSettings();}
  showApplication();
 }catch(error){
  // Le fichier reste consultable en mode local (file:// ou serveur statique sans /api).
  if(location.protocol==='file:'){showApplication();setCloudStatus('Mode local — données dans ce navigateur');}
  else showAuthScreen('Impossible de joindre le serveur. Vérifiez le déploiement Cloudflare puis réessayez.');
 }
}
async function handleLogin(event){
 event.preventDefault();const form=event.currentTarget,btn=form.querySelector('button[type="submit"]');btn.disabled=true;btn.textContent='Connexion…';
 try{await apiRequest('/api/auth/login',{method:'POST',body:JSON.stringify({username:form.username.value.trim(),password:form.password.value})});apiAuthenticated=true;const me=await apiRequest('/api/auth/me');if(me.user?.mustChangePassword){document.getElementById('forceCurrentPassword').value=form.password.value;form.reset();showForcedPasswordScreen();return;}await loadStateFromCloud();if(me.user?.profile)Object.assign(data.settings,{prenom:me.user.profile.firstName||'',nom:me.user.profile.lastName||'',ministere:me.user.profile.ministry||'',service:me.user.profile.department||'',poste:me.user.profile.position||'',phone:me.user.profile.phone||'',email:me.user.profile.email||'',username:me.user.username||'admin'});localStorage.setItem(KEY,JSON.stringify(data));applyPlatformSettings();showApplication();form.reset();document.getElementById('loginUsername').value=data.settings.username||'admin';}
 catch(error){const box=document.getElementById('loginError');box.textContent=error.message||'Identifiants incorrects.';box.style.display='block';}
 finally{btn.disabled=false;btn.textContent='Se connecter';}
}
async function handleForcedPasswordChange(event){
 event.preventDefault();const form=event.currentTarget,button=form.querySelector('button[type="submit"]');const currentPassword=form.currentPassword.value,newPassword=form.newPassword.value,confirmPassword=form.confirmPassword.value;
 const errorBox=document.getElementById('forcePasswordError');
 if(newPassword!==confirmPassword){errorBox.textContent='Les deux nouveaux mots de passe ne correspondent pas.';errorBox.style.display='block';return;}
 if(newPassword.length<10){errorBox.textContent='Le nouveau mot de passe doit contenir au moins 10 caractères.';errorBox.style.display='block';return;}
 button.disabled=true;button.textContent='Modification…';
 try{await apiRequest('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword,newPassword})});apiAuthenticated=false;form.reset();showAuthScreen('Mot de passe modifié. Connectez-vous avec votre nouveau mot de passe.');}
 catch(err){errorBox.textContent=err.message||'Impossible de modifier le mot de passe.';errorBox.style.display='block';}
 finally{button.disabled=false;button.textContent='Modifier le mot de passe et continuer';}
}

async function logoutUser(){
 if(apiAuthenticated){try{await apiRequest('/api/auth/logout',{method:'POST',body:'{}'});}catch(_){} }
 apiAuthenticated=false;showAuthScreen('Vous êtes déconnecté.');document.getElementById('loginPassword').value='';
}
async function saveUserProfile(form){
 const values=Object.fromEntries(new FormData(form).entries());
 const currentPassword=String(values.currentPassword||'');const newPassword=String(values.newPassword||'');
 delete values.currentPassword;delete values.newPassword;
 if(newPassword && !apiAuthenticated)throw new Error('Le changement du mot de passe nécessite une session Cloudflare active.');
 if(newPassword && !currentPassword)throw new Error('Saisissez le mot de passe actuel pour confirmer le changement.');
 if(newPassword && newPassword.length<10)throw new Error('Le nouveau mot de passe doit contenir au moins 10 caractères.');
 Object.assign(data.settings,values);delete data.settings.password;
 save();applyPlatformSettings();
 if(apiAuthenticated){
  await apiRequest('/api/profile',{method:'PUT',body:JSON.stringify({username:values.username,firstName:values.prenom,lastName:values.nom,ministry:values.ministere,department:values.service,position:values.poste,phone:values.phone,email:values.email})});
  if(newPassword){clearTimeout(cloudSyncTimer);await syncStateToCloud();await apiRequest('/api/auth/change-password',{method:'POST',body:JSON.stringify({currentPassword,newPassword})});apiAuthenticated=false;form.elements.currentPassword.value='';form.elements.newPassword.value='';showAuthScreen('Mot de passe modifié. Reconnectez-vous avec votre nouveau mot de passe.');return;}
  alert('Les informations utilisateur ont été enregistrées dans Cloudflare D1.');
 }else{
  alert('Les informations utilisateur ont été enregistrées localement dans ce navigateur.');
 }
 form.elements.currentPassword.value='';form.elements.newPassword.value='';renderSettings();
}


function save(){delete data.settings.password;delete data.settings.currentPassword;delete data.settings.newPassword;localStorage.setItem(KEY,JSON.stringify(data));updateStats();scheduleCloudSync();}
function esc(v){return String(v??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));}
function escAttr(v){return esc(v).replace(/`/g,'&#96;');}
function showView(id,btn){const target=document.getElementById(id);if(!target)return;document.querySelectorAll('.view').forEach(v=>v.classList.remove('active'));target.classList.add('active');document.querySelectorAll('.nav button').forEach(b=>b.classList.remove('active'));const navBtn=btn||document.querySelector(`.nav button[data-menu-id="${id}"]`);if(navBtn)navBtn.classList.add('active');document.querySelector('.main')?.classList.toggle('home-active',id==='accueil');document.getElementById('appRoot')?.classList.toggle('home-landing',id==='accueil');const t={accueil:'Accueil',dashboard:'Tableau de bord',matrice:'Matrice des partenaires',activites:'Activités',partenaires:'Partenaires',indicateurs:'Indicateurs',recherche:'Recherche globale',sauvegarde:'Sauvegarde / restauration',parametres:'Paramètres'};document.getElementById('title').textContent=t[id]||id;if(id==='dashboard')drawCharts();if(id==='activites')renderActivites();if(id==='partenaires')renderPartenairesFiches();if(id==='indicateurs')renderIndicateurs();if(id==='parametres')renderSettings();if(id==='matrice'){renderPartners();renderMatrix()}}
function goToDashboard(){showView('dashboard',document.querySelector('.nav button[data-menu-id="dashboard"]'))}
function toggleCustomType(){let s=document.getElementById('partnerType');document.getElementById('customTypeWrap').style.display=s.value==='__custom__'?'flex':'none'}
function addPartner(){let n=document.getElementById('partnerName').value.trim();if(!n)return alert('Saisissez le nom du partenaire.');let s=document.getElementById('partnerType'),type=s.value==='__custom__'?document.getElementById('customType').value.trim():s.value;if(!type)return alert('Veuillez saisir le nouveau type.');if(data.partners.some(p=>p.name.toLowerCase()===n.toLowerCase()))return alert('Ce partenaire existe déjà.');let values={};rubriques.forEach(r=>values[r]={interet:'',influence:'',contribution:''});data.partners.push({id:Date.now(),name:n,type,values});save();document.getElementById('partnerName').value='';document.getElementById('customType').value='';s.value='Public';toggleCustomType();renderPartners();document.getElementById('partnerSelect').value=data.partners.at(-1).id;renderMatrix();}
function renderPartners(){let s=document.getElementById('partnerSelect'),old=s.value;s.innerHTML='<option value="">-- Sélectionner un partenaire --</option>'+data.partners.map(p=>`<option value="${p.id}">${esc(p.name)} — ${esc(p.type||'Public')}</option>`).join('');if(data.partners.some(p=>String(p.id)===old))s.value=old;}
function deletePartner(){let id=Number(document.getElementById('partnerSelect').value),p=data.partners.find(x=>x.id===id);if(!p)return;if(confirm('Supprimer '+p.name+' et sa matrice ?')){data.partners=data.partners.filter(x=>x.id!==id);save();renderPartners();renderMatrix();}}
function renderMatrix(){let id=Number(document.getElementById('partnerSelect').value),p=data.partners.find(x=>x.id===id),panel=document.getElementById('matrixPanel');if(!p){panel.innerHTML='<div class="empty">Sélectionnez un partenaire.</div>';return}panel.innerHTML=`<h3>Matrice : ${esc(p.name)} <span class="badge">${esc(p.type||'Public')}</span></h3>`+rubriques.map((r,i)=>`<div class="rubric"><h4>${i+1}. ${esc(r)}</h4><div class="criteria">${crit(p,r,'interet','Intérêt')}${crit(p,r,'influence','Influence')}${crit(p,r,'contribution','Contribution')}</div></div>`).join('')+`<div class="actions" style="margin-top:16px"><button class="btn primary" onclick="saveMatrix(${p.id})">Enregistrer la saisie</button><span class="muted">Les informations sont également sauvegardées automatiquement.</span></div>`+summaryBlock(p)+overallPartnersSummary()}
function crit(p,r,k,label){return `<div class="field"><label>${label}</label><textarea oninput="setCrit(${p.id},'${encodeURIComponent(r)}','${k}',this.value)" placeholder="Saisir les informations...">${esc(p.values[r]?.[k])}</textarea></div>`}
function summaryBlock(p){let filled=0;rubriques.forEach(r=>['interet','influence','contribution'].forEach(k=>{if(String(p.values[r]?.[k]||'').trim())filled++}));let pct=Math.round(filled/(rubriques.length*3)*100);return `<div class="panel" style="margin-top:16px;background:#f8fbfc"><h3>Résumé de la saisie</h3><div class="row"><span class="badge">Partenaire : ${esc(p.name)}</span><span class="badge">Type : ${esc(p.type||'Public')}</span><span class="badge">Complétude : ${pct}%</span><button class="btn teal" onclick="exportPartnerExcel(${p.id})">Télécharger cette matrice en Excel</button><button class="btn" onclick="toggleDetailedSummary(${p.id})">Résumé détaillé</button></div><div style="margin-top:12px">${rubriques.map(r=>{let v=p.values[r]||{};let n=['interet','influence','contribution'].filter(k=>String(v[k]||'').trim()).length;return `<div style="padding:5px 0;font-size:12px">${esc(r)} : <b>${n}/3</b></div>`}).join('')}</div></div>`}

function toggleDetailedSummary(pid){const el=document.getElementById('detailedSummary');if(el){el.remove();return}const p=data.partners.find(x=>x.id===pid);if(!p)return;const rows=rubriques.map((r,i)=>{const v=p.values[r]||{};return `<div class="panel" style="margin-top:10px"><div style="font-weight:800;margin-bottom:8px">${i+1}. ${esc(r)}</div><div class="grid3"><div><small>Intérêt</small><div>${esc(v.interet||'Non renseigné')}</div></div><div><small>Influence</small><div>${esc(v.influence||'Non renseigné')}</div></div><div><small>Contribution</small><div>${esc(v.contribution||'Non renseigné')}</div></div></div></div>`}).join('');const wrap=document.createElement('div');wrap.id='detailedSummary';wrap.className='panel';wrap.style.marginTop='14px';wrap.innerHTML=`<h3>Résumé détaillé — ${esc(p.name)}</h3><div class="row"><span class="badge">Type : ${esc(p.type||'Public')}</span><span class="badge">${rubriques.length} rubriques · ${rubriques.length*3} critères</span></div><div style="margin-top:10px">${rows}</div><div style="margin-top:12px"><button class="btn" onclick="document.getElementById('detailedSummary').remove()">Fermer le résumé détaillé</button></div>`;document.getElementById('matrixPanel').appendChild(wrap);wrap.scrollIntoView({behavior:'smooth',block:'start'})}

function setCrit(pid,er,k,v){let p=data.partners.find(x=>x.id===pid);if(p){p.values[decodeURIComponent(er)][k]=v;save()}}
function saveMatrix(pid){let p=data.partners.find(x=>x.id===pid);if(!p)return;save();renderMatrix();setTimeout(()=>{const el=document.getElementById('matrixPanel');if(el)el.scrollIntoView({behavior:'smooth',block:'start'});},50);alert('La saisie de la matrice a été enregistrée avec succès.');}
function obj(form){return Object.fromEntries(new FormData(form).entries())}
function bindForm(type){let form=document.getElementById(type==='multi'?'multiForm':type==='bi'?'biForm':'horsForm');form.onsubmit=e=>{e.preventDefault();let o=obj(form);if(edit[type]){let i=data[type].findIndex(x=>x.id===edit[type]);if(i>=0)data[type][i]={...data[type][i],...o}}else data[type].push({...o,id:Date.now()});save();resetForm(type);renderTables()}}
function resetForm(type){let f=document.getElementById(type+'Form');f.reset();edit[type]=null;document.getElementById(type+'Submit').textContent='Enregistrer'}
function editRow(type,id){let x=data[type].find(a=>a.id===id);if(!x)return;edit[type]=id;let f=document.getElementById(type+'Form');fields[type].forEach(k=>{if(f.elements[k])f.elements[k].value=x[k]||''});document.getElementById(type+'Submit').textContent='Enregistrer la modification';f.scrollIntoView({behavior:'smooth',block:'start'})}
function removeRow(type,id){if(confirm('Supprimer cette ligne ?')){data[type]=data[type].filter(x=>x.id!==id);save();renderTables()}}
function vals(type,key){return [...new Set(data[type].map(x=>x[key]).filter(Boolean))].sort((a,b)=>a.localeCompare(b))}
function fillSelect(id,items,first){let s=document.getElementById(id);let old=s.value;s.innerHTML=`<option value="">${first}</option>`+items.map(x=>`<option>${esc(x)}</option>`).join('');if(items.includes(old))s.value=old}
function filtered(type){let arr=data[type],q=(document.getElementById(type+'Search')?.value||'').toLowerCase();let cat=document.getElementById(type==='multi'?'multiCat':type==='bi'?'biCat': 'horsNature')?.value||'';let sect=document.getElementById(type==='multi'?'multiSect':type==='bi'?'biSect':'horsPays')?.value||'';return arr.filter(x=>{let hay=fields[type].map(k=>x[k]||'').join(' ').toLowerCase();let c=type==='hors'?x.nature:x.categorie;let s=type==='hors'?x.pays:x.secteur;return(!q||hay.includes(q))&&(!cat||c===cat)&&(!sect||s===sect)})}
function renderTables(){fillSelect('multiCat',vals('multi','categorie'),'Toutes les catégories');fillSelect('multiSect',vals('multi','secteur'),'Tous les secteurs');fillSelect('biCat',vals('bi','categorie'),'Toutes les catégories');fillSelect('biSect',vals('bi','secteur'),'Tous les secteurs');fillSelect('horsNature',vals('hors','nature'),'Toutes les natures');fillSelect('horsPays',vals('hors','pays'),'Tous les pays');document.getElementById('multiTable').innerHTML=table('multi',filtered('multi'),fields.multi,['Partenaire','Sigle / Opérateur','Catégorie','Opérateur et instruments','Secteur d’intervention','Observation']);document.getElementById('biTable').innerHTML=table('bi',filtered('bi'),fields.bi,['Partenaire','Sigle opérateur','Catégorie','Opérateur et instruments','Secteur d’interventions','Observations']);document.getElementById('horsTable').innerHTML=table('hors',filtered('hors'),fields.hors,['Numéro','Établissement','Sigle','Nature','Pays de rattachement','Instrument','Observations'])}
function table(type,rows,fs,heads){if(!rows.length)return '<div class="empty">Aucune donnée enregistrée.</div>';return `<div class="tablewrap"><table><thead><tr>${heads.map(h=>`<th>${h}</th>`).join('')}<th>Actions</th></tr></thead><tbody>${rows.map(x=>`<tr>${fs.map(f=>`<td>${esc(x[f])}</td>`).join('')}<td><div class="row"><button class="btn light" onclick="editRow('${type}',${x.id})">Modifier</button><button class="btn danger" onclick="removeRow('${type}',${x.id})">Supprimer</button></div></td></tr>`).join('')}</tbody></table></div>`}
function clearFilter(type){let ids=type==='multi'?['multiSearch','multiCat','multiSect']:type==='bi'?['biSearch','biCat','biSect']:['horsSearch','horsNature','horsPays'];ids.forEach(id=>document.getElementById(id).value='');renderTables()}

function applyPlatformSettings(){
 const s=data.settings||defaultSettings;
 document.querySelector('.brand h1').innerHTML=FIXED_PLATFORM_NAME;
 document.querySelector('.brand p').textContent=FIXED_SUBTITLE;
 const displayName=[s.prenom,s.nom].filter(Boolean).join(' ')||'Utilisateur';
 document.querySelector('.sidebarBottom').innerHTML='<div class="copyright">'+esc(displayName)+'</div>'+FIXED_FOOTER+'<div id="cloudSyncStatus" class="cloud-sync-status" style="color:#d7eef0;margin-top:8px">Connexion…</div><button class="logout-btn" type="button" onclick="logoutUser()">Se déconnecter</button>';
 document.title=FIXED_PLATFORM_NAME;
}
function renderSettings(){
 const s=data.settings||defaultSettings, f=document.getElementById('settingsInfoForm');
 if(f){['prenom','nom','ministere','service','poste','phone','email','username'].forEach(k=>{if(f.elements[k])f.elements[k].value=s[k]??defaultSettings[k]??''});if(f.elements.currentPassword)f.elements.currentPassword.value='';if(f.elements.newPassword)f.elements.newPassword.value='';}
 renderListSetting('rubriquesSettingsList',s.rubriques,'rubrique');renderListSetting('partnerCategoriesSettingsList',s.partnerCategories,'partnerCategory');renderListSetting('contributionTypesSettingsList',s.contributionTypes,'contributionType');renderListSetting('alertStatusesSettingsList',s.alertStatuses,'alertStatus');renderListSetting('partnerContributionTypesSettingsList',s.partnerContributionTypes,'partnerContributionType');renderListSetting('partnerDeliverableTypesSettingsList',s.partnerDeliverableTypes,'partnerDeliverableType');renderListSetting('partnerLitigationResolutionsSettingsList',s.partnerLitigationResolutions,'partnerLitigationResolution');
}
function renderListSetting(elId,arr,type){const el=document.getElementById(elId);if(!el)return;const unique=[...new Set((arr||[]).map(x=>String(x).trim()).filter(Boolean))];el.innerHTML=unique.length?unique.map((x,i)=>`<div class="row" style="margin:5px 0"><input id="${type}_${i}" value="${esc(x)}" style="flex:1;padding:8px;border:1px solid var(--line);border-radius:6px"><button class="btn light" type="button" onclick="renameListItem('${type}',${i})">Modifier</button><button class="btn danger" type="button" onclick="deleteListItem('${type}',${i})">Supprimer</button></div>`).join(''):'<div class="empty" style="padding:12px">Aucune valeur configurée.</div>';}
function listKey(type){return {rubrique:'rubriques',partnerCategory:'partnerCategories',contributionType:'contributionTypes',alertStatus:'alertStatuses',partnerContributionType:'partnerContributionTypes',partnerDeliverableType:'partnerDeliverableTypes',partnerLitigationResolution:'partnerLitigationResolutions'}[type]}
function saveSettings(){save();applyPlatformSettings();updateStats()}
function addListItem(type,value){value=(value||'').trim();const key=listKey(type);if(!value||!key)return;if((data.settings[key]||[]).some(x=>x.toLowerCase()===value.toLowerCase()))return alert('Cette valeur existe déjà.');data.settings[key].push(value);if(type==='rubrique'&&!rubriques.includes(value))rubriques.push(value);saveSettings();renderSettings();syncConfigLists();renderMatrix();}
function renameListItem(type,i){const key=listKey(type),input=document.getElementById(type+'_'+i),value=(input?.value||'').trim();if(!key||!value)return;const arr=data.settings[key];if(arr.some((x,j)=>x.toLowerCase()===value.toLowerCase()&&j!==i))return alert('Cette valeur existe déjà.');const old=arr[i];arr[i]=value;if(type==='rubrique'){const ri=rubriques.indexOf(old);if(ri>=0)rubriques[ri]=value;data.partners.forEach(p=>{if(p.values&&p.values[old]!==undefined){p.values[value]=p.values[old];delete p.values[old];}});}saveSettings();renderSettings();syncConfigLists();renderMatrix();}
function deleteListItem(type,i){const key=listKey(type);if(!key)return;if(data.settings[key].length<=1&&type==='rubrique')return alert('La matrice doit conserver au moins une rubrique.');if(!confirm('Supprimer cette valeur de configuration ? Les données déjà saisies sont conservées.'))return;const old=data.settings[key][i];data.settings[key].splice(i,1);if(type==='rubrique'){const ri=rubriques.indexOf(old);if(ri>=0)rubriques.splice(ri,1);}saveSettings();renderSettings();syncConfigLists();renderMatrix();}
function addRubriqueSetting(){const el=document.getElementById('newRubrique');addListItem('rubrique',el?.value);if(el)el.value='';}
function addPartnerCategory(){const el=document.getElementById('newPartnerCategory');addListItem('partnerCategory',el?.value);if(el)el.value='';}
function addContributionType(){const el=document.getElementById('newContributionType');addListItem('contributionType',el?.value);if(el)el.value='';}
function addAlertStatus(){const el=document.getElementById('newAlertStatus');addListItem('alertStatus',el?.value);if(el)el.value='';}
function addPartnerContributionType(){const el=document.getElementById('newPartnerContributionType');addListItem('partnerContributionType',el?.value);if(el)el.value='';}
function addPartnerDeliverableType(){const el=document.getElementById('newPartnerDeliverableType');addListItem('partnerDeliverableType',el?.value);if(el)el.value='';}
function addPartnerLitigationResolution(){const el=document.getElementById('newPartnerLitigationResolution');addListItem('partnerLitigationResolution',el?.value);if(el)el.value='';}
function syncConfigLists(){
 const cats=data.settings.partnerCategories||[],sel=document.getElementById('pfCategorie');if(sel){const old=sel.value;sel.innerHTML='<option value="">-- Choisir une catégorie --</option>'+cats.map(x=>`<option>${esc(x)}</option>`).join('');if(cats.includes(old))sel.value=old;}
 const pfContrib=document.querySelector('#partenairesForm [name="typeContribution"]');if(pfContrib&&pfContrib.tagName==='SELECT'){const old=pfContrib.value;pfContrib.innerHTML='<option value="">-- Choisir un type de contribution --</option>'+(data.settings.partnerContributionTypes||[]).map(x=>`<option>${esc(x)}</option>`).join('');if((data.settings.partnerContributionTypes||[]).includes(old))pfContrib.value=old;}
 const pfLiv=document.querySelector('#partenairesForm [name="typeLivrable"]');if(pfLiv&&pfLiv.tagName==='SELECT'){const old=pfLiv.value;pfLiv.innerHTML='<option value="">-- Choisir un type de livrable --</option>'+(data.settings.partnerDeliverableTypes||[]).map(x=>`<option>${esc(x)}</option>`).join('');if((data.settings.partnerDeliverableTypes||[]).includes(old))pfLiv.value=old;}
 const pfLit=document.querySelector('#partenairesForm [name="resolutionLitiges"]');if(pfLit&&pfLit.tagName==='SELECT'){const old=pfLit.value;pfLit.innerHTML='<option value="">-- Choisir une résolution --</option>'+(data.settings.partnerLitigationResolutions||[]).map(x=>`<option>${esc(x)}</option>`).join('');if((data.settings.partnerLitigationResolutions||[]).includes(old))pfLit.value=old;}
 const actCat=document.querySelector('#activitesForm [name="categoriePartenaire"]');if(actCat&&actCat.tagName==='SELECT'){const old=actCat.value;actCat.innerHTML='<option value="">-- Choisir une catégorie --</option>'+cats.map(x=>`<option>${esc(x)}</option>`).join('');if(cats.includes(old))actCat.value=old;}
 const contrib=document.querySelector('#activitesForm [name="contribution"]');if(contrib&&contrib.tagName==='SELECT'){const old=contrib.value;contrib.innerHTML='<option value="">-- Choisir --</option>'+(data.settings.contributionTypes||[]).map(x=>`<option>${esc(x)}</option>`).join('');if((data.settings.contributionTypes||[]).includes(old))contrib.value=old;}
 const alerts=document.querySelector('#activitesForm [name="alertes"]');if(alerts&&alerts.tagName==='SELECT'){const old=alerts.value;alerts.innerHTML='<option value="">-- Choisir un statut --</option>'+(data.settings.alertStatuses||[]).map(x=>`<option>${esc(x)}</option>`).join('');if((data.settings.alertStatuses||[]).includes(old))alerts.value=old;}
 renderActivityPartnerOptions();
 renderActivityAxisOptions();
}
function rebuildNavigation(){const nav=document.querySelector('.nav');const core=[['accueil','Accueil','⌂'],['dashboard','Tableau de bord','▦'],['matrice','Matrice','▤'],['partenaires','Partenaires','◉'],['activites','Activités','◉'],['indicateurs','Indicateurs','◈'],['recherche','Recherche globale','⌕'],['sauvegarde','Sauvegarde / restauration','↕'],['parametres','Paramètres','⚙']];nav.innerHTML=core.map(([id,label,icon])=>`<button data-menu-id="${id}" class="${id==='accueil'?'active':''}" onclick="showView('${id}',this)">${icon} &nbsp; ${esc(label)}</button>`).join('');}
function resetSettingsInfo(){const f=document.getElementById('settingsInfoForm');['prenom','nom','ministere','service','poste','phone','email','username','currentPassword','newPassword'].forEach(k=>{if(f.elements[k])f.elements[k].value=defaultSettings[k]??''});['currentPassword','newPassword'].forEach(k=>{if(f.elements[k])f.elements[k].value=''});['prenom','nom','ministere','service','poste','phone','email','username'].forEach(k=>{data.settings[k]=defaultSettings[k]??''});saveSettings();renderSettings();alert('Les informations utilisateur ont été réinitialisées localement.');}
function openFromSettings(id){const b=document.querySelector(`.nav button[data-menu-id="${id}"]`);showView(id,b);}

function updateStats(){let p=data.partners.length,a=(data.activites||[]).length,pf=(data.partenairesFiches||[]).length,ii=data.indicateurs||{},ic=Object.values(ii).filter(v=>v!==''&&v!==null&&v!==undefined).length;document.getElementById('nP').textContent=p;document.getElementById('nPF').textContent=pf;document.getElementById('nA').textContent=a;const ni=document.getElementById('nI');if(ni)ni.textContent=ic;document.getElementById('nT').textContent=p+pf+a;const sp=document.getElementById('setPartnerCount');if(sp)sp.textContent=pf;const sa=document.getElementById('setActivityCount');if(sa)sa.textContent=a;const sm=document.getElementById('setMatrixPartnerCount');if(sm)sm.textContent=p;drawCharts()}
function completion(){let total=data.partners.length*30,filled=0;data.partners.forEach(p=>rubriques.forEach(r=>['interet','influence','contribution'].forEach(k=>{if(String(p.values[r]?.[k]||'').trim())filled++})));return total?Math.round(filled/total*100):0}
function drawCharts(){if(typeof Chart==='undefined')return;Object.values(charts).forEach(c=>c?.destroy());let ctx=document.getElementById('typeChart'),cc=document.getElementById('completionChart');if(!ctx||!cc)return;charts.type=new Chart(ctx,{type:'doughnut',data:{labels:['Partenaires (matrice)','Fiches partenaires','Activités'],datasets:[{data:[data.partners.length,(data.partenairesFiches||[]).length,(data.activites||[]).length]}]},options:{responsive:true,maintainAspectRatio:false,plugins:{title:{display:true,text:'Répartition des enregistrements'}}}});let pct=completion();charts.comp=new Chart(cc,{type:'doughnut',data:{labels:['Matrice renseignée','À renseigner'],datasets:[{data:[pct,100-pct]}]},options:{responsive:true,maintainAspectRatio:false,plugins:{title:{display:true,text:'Taux de complétude de la matrice'}}}})}
function globalSearch(){let q=(document.getElementById('globalSearch').value||'').trim().toLowerCase(),out=[];if(!q){document.getElementById('globalResults').innerHTML='<div class="empty">Saisissez un terme pour rechercher.</div>';return}data.partners.forEach(p=>{let txt=p.name+' '+rubriques.map(r=>Object.values(p.values[r]||{}).join(' ')).join(' ');if(txt.toLowerCase().includes(q))out.push({type:'Matrice',name:p.name,detail:'Partenaire / matrice'});});(data.partenairesFiches||[]).forEach(x=>{let txt=Object.values(x).join(' ').toLowerCase();if(txt.includes(q))out.push({type:'Partenaires',name:x.nom,detail:[x.categorie,x.pays,x.axe,x.secteur,x.telephone,x.email,x.siteWeb].filter(Boolean).join(' • ')})});data.activites.forEach(x=>{let txt=Object.values(x).join(' ').toLowerCase();if(txt.includes(q))out.push({type:'Activités',name:x.nom,detail:[x.axe,x.partenaire,x.contribution,x.alertes].filter(Boolean).join(' • ')})});document.getElementById('globalResults').innerHTML=out.length?`<div class="tablewrap"><table><thead><tr><th>Section</th><th>Élément</th><th>Détails</th></tr></thead><tbody>${out.map(x=>`<tr><td><span class="badge">${esc(x.type)}</span></td><td>${esc(x.name)}</td><td>${esc(x.detail)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Aucun résultat.</div>'}
function backupJSON(){let blob=new Blob([JSON.stringify(data,null,2)],{type:'application/json'}),a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='sauvegarde_matrice_ptf_senegal_'+new Date().toISOString().slice(0,10)+'.json';a.click();URL.revokeObjectURL(a.href)}
function restoreJSON(e){let file=e.target.files[0];if(!file)return;let r=new FileReader();r.onload=()=>{try{let x=JSON.parse(r.result);if(!x.partners) throw Error();data={...x,activites:x.activites||[],partenairesFiches:x.partenairesFiches||[],indicateurs:x.indicateurs||{},settings:{...defaultSettings,...(x.settings||{})}};data.settings.rubriques=data.settings.rubriques||defaultSettings.rubriques.slice();data.settings.rubriques=[...new Set(data.settings.rubriques.map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerCategories=[...new Set(data.settings.partnerCategories.map(v=>String(v).trim()).filter(Boolean))];data.settings.contributionTypes=[...new Set(data.settings.contributionTypes.map(v=>String(v).trim()).filter(Boolean))];data.settings.alertStatuses=[...new Set(data.settings.alertStatuses.map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerContributionTypes=[...new Set((data.settings.partnerContributionTypes||defaultSettings.partnerContributionTypes).map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerDeliverableTypes=[...new Set((data.settings.partnerDeliverableTypes||defaultSettings.partnerDeliverableTypes).map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerLitigationResolutions=[...new Set((data.settings.partnerLitigationResolutions||defaultSettings.partnerLitigationResolutions).map(v=>String(v).trim()).filter(Boolean))];rubriques.splice(0,rubriques.length,...data.settings.rubriques);data.partners.forEach(p=>{p.values=p.values||{};rubriques.forEach(r=>{p.values[r]=p.values[r]||{interet:'',influence:'',contribution:''}})});data.partenairesFiches=(data.partenairesFiches||[]).map(x=>({...x,zone:x.zone||'',siteWeb:x.siteWeb||'',typeContribution:x.typeContribution||'',typeLivrable:x.typeLivrable||x.livrables||'',resolutionLitiges:x.resolutionLitiges||x.litiges||''}));save();applyPlatformSettings();rebuildNavigation();renderPartners();renderMatrix();renderActivites();renderPartenairesFiches();syncConfigLists();renderIndicateurs();updateStats();alert('Sauvegarde restaurée avec succès.')}catch(_){alert('Fichier de sauvegarde invalide.')}};r.readAsText(file);e.target.value=''}
function resetAll(){if(confirm('ATTENTION : effacer toutes les données de la plateforme ?')){data={partners:[],multi:[],bi:[],hors:[],activites:[],partenairesFiches:[],indicateurs:{},settings:JSON.parse(JSON.stringify(defaultSettings))};data.settings.rubriques=[...new Set(data.settings.rubriques.map(v=>String(v).trim()).filter(Boolean))];data.settings.partnerCategories=[...new Set(data.settings.partnerCategories.map(v=>String(v).trim()).filter(Boolean))];data.settings.contributionTypes=[...new Set(data.settings.contributionTypes.map(v=>String(v).trim()).filter(Boolean))];data.settings.alertStatuses=[...new Set(data.settings.alertStatuses.map(v=>String(v).trim()).filter(Boolean))];rubriques.splice(0,rubriques.length,...data.settings.rubriques);data.partners.forEach(p=>{p.values=p.values||{};rubriques.forEach(r=>{p.values[r]=p.values[r]||{interet:'',influence:'',contribution:''}})});save();applyPlatformSettings();rebuildNavigation();renderPartners();renderMatrix();renderActivites();renderPartenairesFiches();syncConfigLists();renderIndicateurs();updateStats();alert('Toutes les données ont été effacées.')}}
function overallPartnersSummary(){
 if(!data.partners.length)return '';
 let total=0,filled=0;
 data.partners.forEach(p=>rubriques.forEach(r=>['interet','influence','contribution'].forEach(k=>{total++;if(String(p.values[r]?.[k]||'').trim())filled++})));
 let pct=total?Math.round(filled/total*100):0;
 let rows=data.partners.map(p=>{let f=0;rubriques.forEach(r=>['interet','influence','contribution'].forEach(k=>{if(String(p.values[r]?.[k]||'').trim())f++}));return `<tr><td>${esc(p.name)}</td><td>${esc(p.type||'Public')}</td><td>${f}/30</td><td>${Math.round(f/(rubriques.length*3)*100)}%</td></tr>`}).join('');
 return `<div class="panel" style="margin-top:16px"><div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><div><h3 style="margin:0">Résumé de l'ensemble des partenaires</h3><div class="muted" style="margin-top:5px">${data.partners.length} partenaire(s) · ${filled}/${total} critères renseignés · complétude globale ${pct}%</div></div><button class="btn green" onclick="exportPartnersSummaryExcel()">Télécharger le résumé global en Excel</button></div><div style="overflow:auto;margin-top:12px"><table><thead><tr><th>Partenaire</th><th>Type</th><th>Critères renseignés</th><th>Complétude</th></tr></thead><tbody>${rows}</tbody></table></div></div>`;
}

function exportPartnerExcel(pid){if(typeof XLSX==='undefined')return alert('La bibliothèque Excel n’est pas disponible.');let p=data.partners.find(x=>x.id===pid);if(!p)return;let rows=rubriques.map(r=>({Partenaire:p.name,Type:p.type||'Public',Rubrique:r,Intérêt:p.values[r].interet||'',Influence:p.values[r].influence||'',Contribution:p.values[r].contribution||''}));let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Matrice');XLSX.writeFile(wb,'Matrice_'+p.name.replace(/[^a-z0-9àâçéèêëîïôûùüÿñ -]/gi,'_').replace(/\s+/g,'_')+'.xlsx')}
function exportPartnersSummaryExcel(){
 if(typeof XLSX==='undefined')return alert('La bibliothèque Excel n’est pas disponible. Vérifiez votre connexion Internet.');
 let summary=data.partners.map(p=>{let f=0;rubriques.forEach(r=>['interet','influence','contribution'].forEach(k=>{if(String(p.values[r]?.[k]||'').trim())f++}));return {Partenaire:p.name,Type:p.type||'Public','Critères renseignés':f,'Total critères':rubriques.length*3,'Complétude':Math.round(f/(rubriques.length*3)*100)+'%'};});
 let detail=[];data.partners.forEach(p=>rubriques.forEach(r=>{let v=p.values[r]||{};detail.push({Partenaire:p.name,Type:p.type||'Public',Rubrique:r,Intérêt:v.interet||'',Influence:v.influence||'',Contribution:v.contribution||''})}));
 let total=summary.reduce((a,x)=>a+x['Critères renseignés'],0),max=data.partners.length*30;
 let global=[{Indicateur:'Nombre de partenaires',Valeur:data.partners.length},{Indicateur:'Critères renseignés',Valeur:total},{Indicateur:'Total critères',Valeur:max},{Indicateur:'Complétude globale',Valeur:(max?Math.round(total/max*100):0)+'%'}];
 let wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(summary),'Résumé partenaires');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(detail),'Matrice détaillée');XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(global),'Indicateurs');XLSX.writeFile(wb,'Resume_ensemble_partenaires_Matrice.xlsx');
}

let activityEdit=null;
function partnerFicheRows(){return (data.partenairesFiches||[]).map(x=>({
 'Nom du partenaire':x.nom,'Catégorie de partenaire':x.categorie,'Pays de rattachement':x.pays,'Axe stratégique SND':x.axe,'Domaine d’intervention':x.secteur,'Durée / Convention - Date début':x.dateDebut,'Durée / Convention - Date fin':x.dateFin,'Zone d’intervention':x.zone,'Type de contribution':x.typeContribution,'Type de financement':x.financement,'Montant':x.montant,'Type de livrable':x.typeLivrable||x.livrables,'Résolution de litiges':x.resolutionLitiges||x.litiges,'Téléphone':x.telephone,'Email':x.email,'Site web du partenaire':x.siteWeb
}));}
function renderPartenairesFiches(){let arr=data.partenairesFiches||[],q=(document.getElementById('partenaireSearch')?.value||'').toLowerCase();arr=arr.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q));let box=document.getElementById('partenaireTable');if(!box)return;if(!arr.length)box.innerHTML='<div class="empty">Aucun partenaire enregistré.</div>';else box.innerHTML='<div class="tablewrap"><table><thead><tr><th>Partenaire</th><th>Catégorie</th><th>Pays</th><th>Axe SND</th><th>Domaine</th><th>Convention</th><th>Zone</th><th>Contribution</th><th>Montant</th><th>Livrable</th><th>Litiges</th><th>Contacts</th><th>Actions</th></tr></thead><tbody>'+arr.map(x=>`<tr><td>${esc(x.nom)}</td><td><span class="badge">${esc(x.categorie)}</span></td><td>${esc(x.pays)}</td><td>${esc(x.axe)}</td><td>${esc(x.secteur)}</td><td>${esc(x.dateDebut||'')} → ${esc(x.dateFin||'')}</td><td>${esc(x.zone)}</td><td>${esc(x.typeContribution)}</td><td>${Number(x.montant||0).toLocaleString('fr-FR')} FCFA</td><td>${esc(x.typeLivrable||x.livrables)}</td><td>${esc(x.resolutionLitiges||x.litiges)}</td><td>${esc(x.telephone)}<br>${esc(x.email)}${x.siteWeb?`<br><a href="${escAttr(x.siteWeb)}" target="_blank" rel="noopener">Site web</a>`:''}</td><td><button class="btn light" onclick="editPartenaireFiche(${x.id})">Modifier</button> <button class="btn danger" onclick="deletePartenaireFiche(${x.id})">Supprimer</button></td></tr>`).join('')+'</tbody></table></div>';renderPartenaireSummary();}
function renderPartenaireSummary(){let a=data.partenairesFiches||[],n=a.length,total=a.reduce((s,x)=>s+Number(x.montant||0),0),cats={};a.forEach(x=>cats[x.categorie]=(cats[x.categorie]||0)+1);let catTxt=Object.entries(cats).map(([k,v])=>`${esc(k)} : <b>${v}</b>`).join(' &nbsp; | &nbsp; ');let el=document.getElementById('partenaireSummary');if(!el)return;el.innerHTML=`<h3>Résumé de la saisie</h3><div class="cards" style="grid-template-columns:repeat(3,1fr);margin-bottom:0"><div class="card"><small>Partenaires saisis</small><div class="num">${n}</div></div><div class="card"><small>Montant total</small><div class="num" style="font-size:21px">${total.toLocaleString('fr-FR')} FCFA</div></div><div class="card"><small>Catégories</small><div style="margin-top:8px;font-size:12px">${catTxt||'Aucune donnée'}</div></div></div><div style="margin-top:14px;font-size:13px"><b>Résumé global :</b> ${n} partenaire(s) enregistré(s), pour un montant cumulé de ${total.toLocaleString('fr-FR')} FCFA.</div><div class="actions" style="margin-top:12px"><button class="btn teal" onclick="exportPartenairesFichesExcel()">Télécharger le résumé des partenaires en Excel</button></div>`;}
