function uniqueActivityPartners(){const names=[];const seen=new Set();[...(data.partenairesFiches||[]).map(x=>x.nom),...(data.partners||[]).map(x=>x.name)].forEach(v=>{const n=String(v||'').trim();if(n&&!seen.has(n.toLowerCase())){seen.add(n.toLowerCase());names.push(n)}});return names}
function normalizeMultiValue(v){if(Array.isArray(v))return v.map(x=>String(x||'').trim()).filter(Boolean);const raw=String(v||'').trim();return raw?raw.split(/\s*\|\s*|\s*;\s*/).map(x=>x.trim()).filter(Boolean):[]}
