function onActivityMultiChange(kind){const boxId=kind==='partners'?'activityPartnersOptions':'activityAxesOptions',valueId=kind==='partners'?'activityPartnersValue':'activityAxesValue',summaryId=kind==='partners'?'activityPartnersSummary':'activityAxesSummary',placeholder=kind==='partners'?'-- Cocher un ou plusieurs partenaires --':'-- Cocher un ou plusieurs axes --';const vals=[...document.querySelectorAll('#'+boxId+' input[type="checkbox"]:checked')].map(x=>x.value);const hidden=document.getElementById(valueId);if(hidden)hidden.value=vals.join(' | ');renderMultiSummary(summaryId,vals,placeholder);}
function renderActivityPartnerOptions(){const box=document.getElementById('activityPartnersOptions');if(!box)return;const current=normalizeMultiValue(document.getElementById('activityPartnersValue')?.value||'');const names=uniqueActivityPartners();box.innerHTML=names.length?names.map(n=>`<label class="multiOption"><input type="checkbox" value="${escAttr(n)}" ${current.some(v=>v.toLowerCase()===n.toLowerCase())?'checked':''} onchange="onActivityMultiChange('partners')"><span>${esc(n)}</span></label>`).join(''):'<div class="empty" style="padding:10px">Aucun partenaire enregistré. Ajoutez d’abord un partenaire.</div>';renderMultiSummary('activityPartnersSummary',current,'-- Cocher un ou plusieurs partenaires --');}
function getActivityAxes(){const set=new Set((data.settings.activityAxes||[]).map(v=>String(v).trim()).filter(Boolean));(data.activites||[]).forEach(x=>normalizeMultiValue(x.axes||x.axe).forEach(v=>set.add(v)));return [...set]}
function renderActivityAxisOptions(){const box=document.getElementById('activityAxesOptions');if(!box)return;const current=normalizeMultiValue(document.getElementById('activityAxesValue')?.value||'');const axes=getActivityAxes();box.innerHTML=axes.length?axes.map(a=>`<label class="multiOption"><input type="checkbox" value="${escAttr(a)}" ${current.some(v=>v.toLowerCase()===a.toLowerCase())?'checked':''} onchange="onActivityMultiChange('axes')"><span>${esc(a)}</span></label>`).join(''):'<div class="empty" style="padding:10px">Aucun axe configuré. Ajoutez une possibilité ci-dessous.</div>';renderMultiSummary('activityAxesSummary',current,'-- Cocher un ou plusieurs axes --');}
