function renderActivites(){let arr=data.activites||[],q=(document.getElementById('activiteSearch')?.value||'').toLowerCase();arr=arr.filter(x=>Object.values(x).join(' ').toLowerCase().includes(q));let box=document.getElementById('activiteTable');if(!arr.length)box.innerHTML='<div class="empty">Aucune activité enregistrée.</div>';else box.innerHTML='<div class="tablewrap"><table><thead><tr><th>Structure</th><th>Division</th><th>Activité</th><th>Date</th><th>Axe SND</th><th>Budget</th><th>Partenaires</th><th>Catégorie</th><th>Zone</th><th>Respect délais</th><th>Alertes</th><th>Actions</th></tr></thead><tbody>'+arr.map(x=>`<tr><td>${esc(x.structure||'—')}</td><td>${esc(x.division||'—')}</td><td>${esc(x.nom)}</td><td>${esc(x.dateDebut||'')} → ${esc(x.dateFin||'')}</td><td>${esc(normalizeMultiValue(x.axes||x.axe).join(" • "))}</td><td>${Number(x.budget||0).toLocaleString('fr-FR')} FCFA</td><td>${esc(normalizeMultiValue(x.partenaires||x.partenaire).join(" • "))}</td><td>${esc(x.categoriePartenaire)}</td><td>${esc(x.zone)}</td><td>${esc(x.respectDelais||0)}%</td><td><span class="badge">${esc(x.alertes)}</span></td><td><button class="btn light" onclick="editActivite(${x.id})">Modifier</button> <button class="btn danger" onclick="deleteActivite(${x.id})">Supprimer</button></td></tr>`).join('')+'</tbody></table></div>';renderActiviteSummary();}
function renderActiviteSummary(){
 let a=data.activites||[],n=a.length,totalB=a.reduce((s,x)=>s+Number(x.budget||0),0),ex=n?a.reduce((s,x)=>s+Number(x.execution||0),0)/n:0,lv=n?a.reduce((s,x)=>s+Number(x.livrables||0),0)/n:0,rd=n?a.reduce((s,x)=>s+Number(x.respectDelais||0),0)/n:0,alerts=a.filter(x=>x.alertes&&x.alertes!=='Aucune alerte').length;
 const detailRows=a.length?a.map(x=>`<tr><td>${esc(x.structure||'—')}</td><td>${esc(x.division||'—')}</td><td>${esc(x.nom||'—')}</td></tr>`).join(''):'<tr><td colspan="3" class="empty">Aucune saisie à résumer.</td></tr>';
 const el=document.getElementById('activiteSummary');if(!el)return;
 el.innerHTML=`<h3>Résumé de la saisie</h3><div class="cards" style="grid-template-columns:repeat(5,1fr);margin-bottom:0"><div class="card"><small>Activités saisies</small><div class="num">${n}</div></div><div class="card"><small>Budget total</small><div class="num" style="font-size:21px">${totalB.toLocaleString('fr-FR')} FCFA</div></div><div class="card"><small>Exécution moyenne</small><div class="num">${ex.toFixed(1)}%</div></div><div class="card"><small>Respect délais</small><div class="num">${rd.toFixed(1)}%</div></div><div class="card"><small>Alertes à suivre</small><div class="num">${alerts}</div></div></div><div style="margin-top:12px;font-size:13px"><b>Réalisation moyenne des livrables :</b> ${lv.toFixed(1)}% &nbsp; | &nbsp; <b>Activités avec alerte :</b> ${alerts}</div><div style="margin-top:16px"><h4 style="margin:0 0 9px;color:var(--p)">Structures et divisions des activités enregistrées</h4><div class="tablewrap"><table style="min-width:520px"><thead><tr><th>Structure</th><th>Division</th><th>Nom de l’activité</th></tr></thead><tbody>${detailRows}</tbody></table></div></div><div class="actions" style="margin-top:12px"><button class="btn teal" onclick="exportActivitesExcel()">Télécharger le résumé des activités en Excel</button></div>`;
}
