function exportActivitesExcel(){if(typeof XLSX==='undefined')return alert('La bibliothèque Excel n’est pas disponible.');let wb=XLSX.utils.book_new(),rows=activityRows();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet(rows),'Activités');let n=rows.length,total=rows.reduce((s,x)=>s+Number(x['Budget alloué (FCFA)']||0),0),ex=n?rows.reduce((s,x)=>s+parseFloat(x['Taux d’exécution']||0),0)/n:0,lv=n?rows.reduce((s,x)=>s+parseFloat(x['Taux de réalisation des livrables']||0),0)/n:0,rd=n?rows.reduce((s,x)=>s+parseFloat(x['Taux respect des délais']||0),0)/n:0;XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{Indicateur:'Nombre d’activités',Valeur:n},{Indicateur:'Budget total (FCFA)',Valeur:total},{Indicateur:'Taux moyen d’exécution',Valeur:ex.toFixed(1)+'%'},{Indicateur:'Taux moyen de réalisation des livrables',Valeur:lv.toFixed(1)+'%'},{Indicateur:'Taux moyen respect des délais',Valeur:rd.toFixed(1)+'%'},{Indicateur:'Activités avec alerte',Valeur:(data.activites||[]).filter(x=>x.alertes!=='Aucune alerte').length}]),'Résumé');XLSX.writeFile(wb,'Resume_Activites_SND.xlsx');}

function setIndicateurAlerte(value){const input=document.getElementById('indAlerte');if(input)input.value=value;document.querySelectorAll('.alertChoice').forEach(b=>b.classList.toggle('active',b.dataset.alert===value));}
function determinerAlerteIndicateur(datePrevue,dateReelle){
  if(!datePrevue)return '';
  const prevue=new Date(datePrevue+'T00:00:00');
  if(Number.isNaN(prevue.getTime()))return '';
  const reference=dateReelle?new Date(dateReelle+'T00:00:00'):new Date();
  if(Number.isNaN(reference.getTime()))return '';
  const ecart=Math.round((prevue-reference)/86400000);
  // Priorité aux règles demandées : retard si la date réelle dépasse la date prévue;
  // risque si l'échéance est à 2 jours ou moins; sinon à temps.
  if(dateReelle && ecart<0)return 'rouge';
  if(ecart>=0 && ecart<=2)return 'jaune';
  if(ecart>=0 && ecart<=5)return 'vert';
  if(ecart>5)return 'vert';
  return 'vert';
}
function calculerIndicateurs(){const a=Number(document.getElementById('indBudgetAlloue')?.value||0),d=Number(document.getElementById('indBudgetDepense')?.value||0),lv=Number(document.getElementById('indLivrablesValides')?.value||0),lp=Number(document.getElementById('indLivrablesPrevus')?.value||0);document.getElementById('indBudgetRapport').value=a>0?(d/a*100).toFixed(2):'';document.getElementById('indLivrablesTaux').value=lp>0?(lv/lp*100).toFixed(2):'';const p=document.getElementById('indDatePrevue')?.value,r=document.getElementById('indDateReelle')?.value;let ec='';if(p&&r){const delta=Math.round((new Date(p+'T00:00:00')-new Date(r+'T00:00:00'))/86400000);ec=delta>0?'+'+delta+' jour'+(delta>1?'s':''):delta+' jour'+(Math.abs(delta)>1?'s':'');}document.getElementById('indEcart').value=ec;const alerte=determinerAlerteIndicateur(p,r);setIndicateurAlerte(alerte||'vert');}
function resetIndicateurs(){if(!confirm('Réinitialiser toutes les données des indicateurs ?'))return;data.indicateurs={};save();renderIndicateurs();}
function saveIndicateurs(){calculerIndicateurs();data.indicateurs={budgetAlloue:Number(document.getElementById('indBudgetAlloue').value||0),budgetDepense:Number(document.getElementById('indBudgetDepense').value||0),budgetRapport:Number(document.getElementById('indBudgetRapport').value||0),livrablesValides:Number(document.getElementById('indLivrablesValides').value||0),livrablesPrevus:Number(document.getElementById('indLivrablesPrevus').value||0),livrablesTaux:Number(document.getElementById('indLivrablesTaux').value||0),datePrevue:document.getElementById('indDatePrevue').value,dateReelle:document.getElementById('indDateReelle').value,ecart:document.getElementById('indEcart').value,alerte:document.getElementById('indAlerte').value,sexe:document.getElementById('indSexe').value===''?'':Number(document.getElementById('indSexe').value),age:document.getElementById('indAge').value.trim(),region:document.getElementById('indRegion').value,urbain:Number(document.getElementById('indUrbain').value||0),rural:Number(document.getElementById('indRural').value||0)};save();renderIndicateurs();alert('Les indicateurs ont été enregistrés.');}
function syncIndicateurInputs(){const i=data.indicateurs||{};['budgetAlloue','budgetDepense','budgetRapport','livrablesValides','livrablesPrevus','livrablesTaux','datePrevue','dateReelle','ecart','sexe','age','region','urbain','rural'].forEach(k=>{const el=document.getElementById('ind'+k.charAt(0).toUpperCase()+k.slice(1));if(el)el.value=i[k]??'';});setIndicateurAlerte(i.alerte||'vert');}
function renderIndicateurs(){syncIndicateurInputs();calculerIndicateurs();const i=data.indicateurs||{};const el=document.getElementById('indicateursSummary');if(!el)return;el.innerHTML=`<h3>Résumé des indicateurs</h3><div class="cards" style="grid-template-columns:repeat(4,1fr);margin-bottom:0"><div class="card"><small>Taux de consommation des crédits</small><div class="num">${Number(i.budgetRapport||document.getElementById('indBudgetRapport')?.value||0).toFixed(2)}%</div></div><div class="card"><small>Taux de réalisation des livrables</small><div class="num">${Number(i.livrablesTaux||document.getElementById('indLivrablesTaux')?.value||0).toFixed(2)}%</div></div><div class="card"><small>Respect des délais</small><div class="num" style="font-size:18px">${esc(i.ecart||document.getElementById('indEcart')?.value||'—')}</div></div><div class="card"><small>Urbain / Rural</small><div class="num" style="font-size:19px">${Number(i.urbain||0)} / ${Number(i.rural||0)}</div></div></div><div style="margin-top:12px;font-size:12px">Budget : <b>${Number(i.budgetDepense||0).toLocaleString('fr-FR')} / ${Number(i.budgetAlloue||0).toLocaleString('fr-FR')} FCFA</b> · Alerte : <span class="alertChoice ${i.alerte==='jaune'?'alertYellow':i.alerte==='rouge'?'alertRed':'alertGreen'} active" style="display:inline-block;padding:4px 9px;font-size:11px">${i.alerte==='jaune'?'Si risque':i.alerte==='rouge'?'En retard':'À temps'}</span> · Région : <b>${esc(i.region||'—')}</b></div>`;}
['indBudgetAlloue','indBudgetDepense','indLivrablesValides','indLivrablesPrevus','indDatePrevue','indDateReelle'].forEach(id=>document.getElementById(id)?.addEventListener(id.includes('Date')?'change':'input',calculerIndicateurs));

