// Horloge de la page d'accueil : date et heure du Sénégal (Africa/Dakar).
(function initSenegalWelcomeClock(){
 const dateEl=document.getElementById('home-current-date');
 const timeEl=document.getElementById('home-current-time');
 if(!dateEl||!timeEl)return;
 const dateFmt=new Intl.DateTimeFormat('fr-FR',{timeZone:'Africa/Dakar',weekday:'long',day:'numeric',month:'long',year:'numeric'});
 const timeFmt=new Intl.DateTimeFormat('fr-FR',{timeZone:'Africa/Dakar',hour:'2-digit',minute:'2-digit',second:'2-digit',hourCycle:'h23'});
 function tick(){const now=new Date();const d=dateFmt.format(now);dateEl.textContent=d.charAt(0).toLocaleUpperCase('fr-FR')+d.slice(1);timeEl.textContent=timeFmt.format(now);}
 tick();window.setInterval(tick,1000);
})();
